const r=e=>{if(e==null||isNaN(e))return"₹ 0.00";const t=Number(e);return new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",minimumFractionDigits:2,maximumFractionDigits:2}).format(t).replace("INR","₹")},n=e=>{if(!e)return"-";const t=new Date(e);return isNaN(t.getTime())?e:new Intl.DateTimeFormat("en-IN",{timeZone:"Asia/Kolkata",day:"2-digit",month:"short",year:"numeric"}).format(t)},i=e=>{if(!e)return"-";const t=new Date(e);return isNaN(t.getTime())?e:new Intl.DateTimeFormat("en-IN",{timeZone:"Asia/Kolkata",day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit",hour12:!0}).format(t)},a=e=>{if(!e)return"-";const t=new Date(e);return isNaN(t.getTime())?e:new Intl.DateTimeFormat("en-IN",{timeZone:"Asia/Kolkata",hour:"2-digit",minute:"2-digit",hour12:!0}).format(t)},m=e=>{if(!e)return"-";const t=(""+e).replace(/\D/g,"");return t.length===10?`+91 ${t.slice(0,5)} ${t.slice(5)}`:e};export{a,m as b,i as c,n as d,r as f};
